-- Offline database schema foundation; application queries not migrated yet.
PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY AUTOINCREMENT, fullname TEXT NOT NULL, email TEXT NOT NULL UNIQUE, password TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'admin' CHECK(role='admin'), created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS auth_sessions (id TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at TEXT NOT NULL, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS password_reset_tokens (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, token_hash TEXT NOT NULL UNIQUE, expires_at TEXT NOT NULL, used_at TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS security_rate_limits (bucket_key TEXT PRIMARY KEY, window_started INTEGER NOT NULL, hits INTEGER NOT NULL, last_seen INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS patients (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, address TEXT, phone TEXT, age INTEGER, occupation TEXT, gender TEXT CHECK(gender IN ('Male','Female')), status TEXT, complain TEXT, image TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS visits (id INTEGER PRIMARY KEY AUTOINCREMENT, patient_id INTEGER NOT NULL REFERENCES patients(id) ON DELETE CASCADE, visit_date TEXT, visit_time TEXT, procedure_name TEXT, complain TEXT, description TEXT, amount_paid NUMERIC DEFAULT 0, balance NUMERIC DEFAULT 0, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS dental_chart (id INTEGER PRIMARY KEY AUTOINCREMENT, patient_id INTEGER NOT NULL REFERENCES patients(id) ON DELETE CASCADE, visit_id INTEGER REFERENCES visits(id) ON DELETE SET NULL, tooth_number TEXT NOT NULL, condition_name TEXT NOT NULL, notes TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP, updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS appointments (id INTEGER PRIMARY KEY AUTOINCREMENT, patient_id INTEGER REFERENCES patients(id) ON DELETE SET NULL, fullname TEXT NOT NULL, email TEXT NOT NULL, phone TEXT NOT NULL, preferred_date TEXT NOT NULL, preferred_time TEXT NOT NULL, service TEXT NOT NULL, reason TEXT, status TEXT NOT NULL DEFAULT 'Pending', remarks TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS queue (id INTEGER PRIMARY KEY AUTOINCREMENT, queue_number INTEGER NOT NULL, patient_id INTEGER REFERENCES patients(id) ON DELETE SET NULL, appointment_id INTEGER REFERENCES appointments(id) ON DELETE SET NULL, patient_name TEXT NOT NULL, queue_type TEXT NOT NULL, service TEXT, reason TEXT, priority TEXT NOT NULL DEFAULT 'Normal', status TEXT NOT NULL DEFAULT 'Waiting', queue_date TEXT NOT NULL, check_in_time TEXT, called_at TEXT, treatment_started_at TEXT, completed_at TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP, UNIQUE(queue_date, queue_number));
CREATE TABLE IF NOT EXISTS queue_daily_sequence (queue_date TEXT PRIMARY KEY, last_number INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS payments (id INTEGER PRIMARY KEY AUTOINCREMENT, visit_id INTEGER NOT NULL REFERENCES visits(id) ON DELETE CASCADE, patient_id INTEGER NOT NULL REFERENCES patients(id) ON DELETE CASCADE, amount NUMERIC NOT NULL DEFAULT 0, payment_method TEXT NOT NULL, reference_number TEXT, notes TEXT, paid_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_visits_date ON visits(visit_date);
CREATE INDEX IF NOT EXISTS idx_queue_date ON queue(queue_date,status);
CREATE INDEX IF NOT EXISTS idx_appointments_date ON appointments(preferred_date,status);
CREATE INDEX IF NOT EXISTS idx_payments_paid_at ON payments(paid_at);
